<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>YouTube Creators - Make Money on YouTube</title>
<style>
  *{box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    margin:0;
    color:#0b0b0b;
    font-family:Arial,Helvetica,sans-serif;
    font-size:18px;
    line-height:1.55;
    background:#fff;
  }
  header{
    height:68px;
    border-bottom:1px solid #e5e5e5;
    display:flex;
    align-items:center;
    padding:0 24px;
    position:sticky;
    top:0;
    z-index:20;
    background:#fff;
  }
  .brand{
    display:flex;
    align-items:center;
    width:205px;
    flex:none;
    color:#111;
    font-weight:700;
    font-size:21px;
    letter-spacing:-1.3px;
  }
  .ytmark{
    width:32px;
    height:23px;
    background:#f00;
    border-radius:7px;
    margin-right:5px;
    position:relative;
  }
  .ytmark:after{
    content:"";
    position:absolute;
    left:12px;
    top:6px;
    border-left:10px solid white;
    border-top:6px solid transparent;
    border-bottom:6px solid transparent;
  }
  nav{
    display:flex;
    align-items:center;
    gap:64px;
    height:100%;
  }
  nav a{
    text-decoration:none;
    color:#555;
    font-size:15px;
    font-weight:600;
    white-space:nowrap;
  }
  nav a:hover{color:#111}
  .chev{
    display:inline-block;
    width:8px;
    height:8px;
    border-right:2px solid #555;
    border-bottom:2px solid #555;
    transform:rotate(45deg) translateY(-2px);
    margin-left:7px;
  }
  .search{
    margin-left:auto;
    width:22px;
    height:22px;
    border:2px solid #111;
    border-radius:50%;
    position:relative;
    cursor:pointer;
  }
  .search:after{
    content:"";
    width:8px;height:2px;background:#111;
    position:absolute;right:-6px;bottom:0;
    transform:rotate(48deg);
  }
  .btn{cursor:pointer}
  main{width:100%}
  .hero{
    width:840px;
    height:545px;
    margin:66px auto 0;
    border:1px solid #f0f0f0;
    text-align:center;
    padding-top:8px;
  }
  .hero img{
    display:block;
    width:92px;
    height:92px;
    object-fit:contain;
    margin:0 auto 23px;
  }
  .hero h1{
    font-size:68px;
    line-height:1.08;
    letter-spacing:-3px;
    margin:0 auto;
    max-width:790px;
    font-weight:700;
  }
  .hero p{
    width:650px;
    margin:55px auto 0;
    font-size:18px;
    line-height:1.65;
  }
  .partner{
    width:1460px;
    margin:105px auto 0;
    display:grid;
    grid-template-columns:600px 1fr;
    gap:145px;
    min-height:610px;
  }
  .partner h2{
    font-size:46px;
    line-height:1.15;
    margin:0 0 32px;
    letter-spacing:-1.8px;
  }
  .partner-copy p{
    margin:0;
    font-size:18px;
    line-height:1.68;
  }
  .partner-media{
    padding-top:0;
    text-align:center;
  }
  .partner-media img{
    width:680px;
    height:475px;
    object-fit:contain;
    object-position:top center;
    display:block;
  }
  .accordion{
    margin-top:30px;
    border-top:1px solid #c9c9c9;
  }
  .acc-item{
    border-bottom:1px solid #c9c9c9;
  }
  .acc-head{
    min-height:68px;
    display:flex;
    align-items:center;
    justify-content:space-between;
    font-size:22px;
    padding:0;
    color:#222;
  }
  .acc-head .arrow{
    width:9px;height:9px;
    border-right:2px solid #777;
    border-bottom:2px solid #777;
    transform:rotate(45deg);
    margin-right:7px;
    transition:.2s;
  }
  .acc-item.open .arrow{transform:rotate(225deg) translate(-2px,-2px)}
  .acc-body{
    display:none;
    padding:0 0 20px;
    color:#666;
    font-size:18px;
    line-height:1.62;
  }
  .acc-item.open .acc-body{display:block}
  .acc-body p{margin:0 0 22px}
  .acc-body ul{margin:8px 0 25px;padding-left:34px}
  .acc-body li{padding-left:4px;margin-bottom:18px}
  .acc-body a,.link{
    color:#1769b0;
    font-weight:600;
    text-decoration:none;
  }
  .external:after{
    content:"↗";
    font-size:22px;
    font-weight:400;
    margin-left:8px;
  }
  .ways{
    width:1080px;
    margin:45px auto 0;
    text-align:center;
  }
  .ways h2,.next h2{
    font-size:46px;
    line-height:1.2;
    letter-spacing:-1.8px;
    margin:0 0 30px;
  }
  .ways .intro{
    width:700px;
    margin:0 auto;
    font-size:18px;
    line-height:1.6;
  }
  .note{
    color:#777;
    font-size:15px;
    margin:24px auto 74px;
    max-width:650px;
  }
  .earnings{
    text-align:left;
    border-top:1px solid #bbb;
  }
  .earn-item{border-bottom:1px solid #bbb}
  .earn-head{
    height:77px;
    display:flex;
    align-items:center;
    gap:24px;
    font-size:22px;
  }
  .num{
    width:42px;height:42px;border-radius:50%;
    background:#f2f2f2;
    display:flex;align-items:center;justify-content:center;
    font-size:14px;font-weight:bold;color:#666;
    flex:none;
  }
  .earn-item.open .num{background:#d00212;color:#fff}
  .earn-arrow{
    margin-left:auto;
    width:9px;height:9px;
    border-right:2px solid #777;
    border-bottom:2px solid #777;
    transform:rotate(45deg);
    margin-right:7px;
  }
  .earn-item.open .earn-arrow{transform:rotate(225deg) translate(-2px,-2px)}
  .earn-content{
    display:none;
    padding:3px 0 42px;
    min-height:250px;
  }
  .earn-item.open .earn-content{display:grid;grid-template-columns:510px 1fr;gap:50px}
  .earn-content img{
    width:510px;height:285px;object-fit:cover;object-position:center;
  }
  .earn-content p{margin:0 0 20px;line-height:1.62}
  .next{
    width:800px;
    text-align:center;
    margin:170px auto 130px;
  }
  .next p{font-size:18px;line-height:1.6}
  @media(max-width:1100px){
    nav{gap:25px}.partner{width:90%;grid-template-columns:1fr;gap:20px}
    .partner-media img{width:100%}.ways{width:90%}
  }
</style>
</head>
<body>
<header>
  <a class="brand btn" href="#top" aria-label="YouTube Creators">
    <span class="ytmark"></span><span>YouTube Creators</span>
